using Microsoft.EntityFrameworkCore;using accounts-management.Models;namespace accounts-management.Data{public class ApplicationDbContext:DbContext{public ApplicationDbContext(DbContextOptions<ApplicationDbContext> options):base(options){}public DbSet<Account> Accounts=>Set<Account>();protected override void OnModelCreating(ModelBuilder modelBuilder){base.OnModelCreating(modelBuilder);modelBuilder.Entity<Account>(entity=>{entity.ToTable("accounts");entity.Property(e=>e.Id).HasColumnName("id");entity.Property(e=>e.Name).HasColumnName("name");entity.Property(e=>e.Email).HasColumnName("email");entity.Property(e=>e.Address).HasColumnName("address");});}}}